#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<vector<int>> g(N);
    vector<int> deg(N, 0);

    for (int i = 0; i < M; i++) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        g[a].push_back(b);
        g[b].push_back(a);
        deg[a]++;
        deg[b]++;
    }

    // Necessary condition: graph can be decomposed into circuits iff all degrees are even.
    for (int i = 0; i < N; i++) {
        if (deg[i] % 2) {
            cout << "No\n";
            return 0;
        }
    }

    int cnt4 = 0;
    int cnt6plus = 0;
    vector<int> fourVerts;

    for (int i = 0; i < N; i++) {
        if (deg[i] >= 6) cnt6plus++;
        if (deg[i] >= 4) cnt4++;
        if (deg[i] == 4) fourVerts.push_back(i);
    }

    // Standard characterization:
    // - if some vertex has degree >= 6, answer is Yes
    // - if at least three vertices have degree >= 4, answer is Yes
    // - if fewer than two vertices have degree >= 4, answer is No
    // - if exactly two vertices have degree 4 and all others degree 2 or 0,
    //   need to check whether there exists a path between those two using all degree-2 vertices;
    //   if every component between branches is just a single chain connecting them, answer is No,
    //   otherwise Yes.
    if (cnt6plus >= 1) {
        cout << "Yes\n";
        return 0;
    }
    if (cnt4 >= 3) {
        cout << "Yes\n";
        return 0;
    }
    if (cnt4 <= 1) {
        cout << "No\n";
        return 0;
    }

    // Now exactly two vertices have degree 4, call them s and t.
    int s = fourVerts[0], t = fourVerts[1];

    // From each neighbor of s, walk through degree-2 vertices.
    // If one such walk reaches t, then that branch is a direct s-t chain.
    // If all 4 branches from s reach t, graph is essentially two vertices joined by 4 edge-disjoint chains,
    // which cannot produce 3 circuits. Otherwise, answer is Yes.
    for (int nei : g[s]) {
        int prev = s;
        int cur = nei;
        while (deg[cur] == 2) {
            int nxt = g[cur][0] ^ g[cur][1] ^ prev;
            prev = cur;
            cur = nxt;
        }
        if (cur == s) continue; // found a cycle attached to s alone => enough
        if (cur != t) {
            cout << "Yes\n";
            return 0;
        }
    }

    cout << "No\n";
    return 0;
}

