#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct Edge {
    int to;
    int next;
} Edge;

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int *deg = (int *)calloc(N + 1, sizeof(int));
    int *head = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) head[i] = -1;

    Edge *edges = (Edge *)malloc((2 * M) * sizeof(Edge));
    int ecnt = 0;

    for (int i = 0; i < M; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        deg[a]++;
        deg[b]++;

        edges[ecnt].to = b;
        edges[ecnt].next = head[a];
        head[a] = ecnt++;

        edges[ecnt].to = a;
        edges[ecnt].next = head[b];
        head[b] = ecnt++;
    }

    // Necessary condition for decomposition into circuits:
    // every vertex must have even degree.
    for (int i = 1; i <= N; i++) {
        if (deg[i] % 2) {
            printf("No\n");
            free(deg);
            free(head);
            free(edges);
            return 0;
        }
    }

    int cnt4 = 0;
    int has6 = 0;
    int special4 = -1;

    for (int i = 1; i <= N; i++) {
        if (deg[i] >= 6) has6 = 1;
        if (deg[i] == 4) {
            cnt4++;
            special4 = i;
        }
    }

    // Standard characterization:
    // - if some vertex has degree >= 6 -> Yes
    // - else if at least three vertices have degree 4 -> Yes
    // - else if fewer than two vertices have degree 4 -> No
    // - else exactly two vertices have degree 4:
    //   Yes iff there exists a path between them avoiding one of the two
    //   edge-disjoint chains of the "theta" obstruction, equivalently
    //   after removing the special degree-4 vertex from DFS start,
    //   we can return to it before reaching the other degree-4 vertex.
    if (has6 || cnt4 >= 3) {
        printf("Yes\n");
        free(deg);
        free(head);
        free(edges);
        return 0;
    }

    if (cnt4 <= 1) {
        printf("No\n");
        free(deg);
        free(head);
        free(edges);
        return 0;
    }

    // cnt4 == 2
    // Let one degree-4 vertex be s.
    // Explore from each neighbor of s without passing through s.
    // If some branch reaches the other degree-4 vertex t, then that branch
    // is one of the two mandatory chains.
    // If some branch closes back to another neighbor of s without touching t,
    // then we can form 3 circuits => Yes.
    int s = special4;
    int *mark = (int *)calloc(N + 1, sizeof(int));
    int token = 0;

    int neigh[4], k = 0;
    for (int e = head[s]; e != -1; e = edges[e].next) {
        neigh[k++] = edges[e].to;
    }

    for (int i = 0; i < k; i++) {
        token++;
        int start = neigh[i];

        int *stack = (int *)malloc((N + 5) * sizeof(int));
        int top = 0;
        stack[top++] = start;
        mark[start] = token;

        int found_other4 = 0;
        int found_back_to_s_neighbor = 0;

        while (top) {
            int v = stack[--top];
            if (v != s && deg[v] == 4) {
                found_other4 = 1;
            }
            for (int e = head[v]; e != -1; e = edges[e].next) {
                int to = edges[e].to;
                if (to == s) continue;
                if (mark[to] == token) continue;
                mark[to] = token;
                stack[top++] = to;
            }
        }

        // If this component (after removing s) does not contain the other degree-4
        // vertex, then it yields a cycle attached at s, giving 3 circuits.
        if (!found_other4) {
            printf("Yes\n");
            free(stack);
            free(mark);
            free(deg);
            free(head);
            free(edges);
            return 0;
        }
        free(stack);
    }

    printf("No\n");

    free(mark);
    free(deg);
    free(head);
    free(edges);
    return 0;
}

