import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Edge {
        int to, id;
        Edge(int to, int id) {
            this.to = to;
            this.id = id;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();
        int M = fs.nextInt();

        ArrayList<Edge>[] g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();

        int[] deg = new int[N];
        for (int i = 0; i < M; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            g[a].add(new Edge(b, i));
            g[b].add(new Edge(a, i));
            deg[a]++;
            deg[b]++;
        }

        // Necessary condition: every degree must be even
        for (int i = 0; i < N; i++) {
            if ((deg[i] & 1) != 0) {
                System.out.println("No");
                return;
            }
        }

        // Let cyclomatic number be r = M - N + 1 (connected graph).
        // If r < 3, impossible to partition all edges into 3 circuits.
        int r = M - N + 1;
        if (r < 3) {
            System.out.println("No");
            return;
        }

        // If some vertex has degree >= 6, answer is Yes.
        for (int i = 0; i < N; i++) {
            if (deg[i] >= 6) {
                System.out.println("Yes");
                return;
            }
        }

        // If at least three vertices have degree 4, answer is Yes.
        int cnt4 = 0;
        ArrayList<Integer> deg4Vertices = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            if (deg[i] == 4) {
                cnt4++;
                deg4Vertices.add(i);
            }
        }
        if (cnt4 >= 3) {
            System.out.println("Yes");
            return;
        }

        // Remaining possible Yes-case:
        // exactly two degree-4 vertices and all others degree 2.
        // Then answer is Yes iff there is NOT a simple path between the two
        // degree-4 vertices using all edges of the graph.
        // Equivalently, after removing one degree-4 vertex s, from each of its
        // 4 incident edges, if following degree-2 chain reaches the other degree-4
        // vertex t in all 4 cases, then No; otherwise Yes.
        if (cnt4 != 2) {
            System.out.println("No");
            return;
        }

        int s = deg4Vertices.get(0);
        int t = deg4Vertices.get(1);

        int hitT = 0;
        for (Edge e : g[s]) {
            int prev = s;
            int cur = e.to;

            while (cur != t && deg[cur] == 2) {
                Edge e0 = g[cur].get(0);
                Edge e1 = g[cur].get(1);
                int nxt = (e0.to == prev) ? e1.to : e0.to;
                prev = cur;
                cur = nxt;
            }

            if (cur == t) hitT++;
        }

        System.out.println(hitT == 4 ? "No" : "Yes");
    }
}
